// Example: a shared helper that encapsulates the repeated pattern
function scanAnchoredFiles<T>(
  ctx: CheckContext,
  anchor: EdgeAnchor,
  fileGuard: (text: string) => boolean,
  lineGuard: (line: string) => boolean,
  windowFn: (lines: string[], i: number) => string,
  onMatch: (file: string, lines: string[], i: number, win: string) => T | null,
): T[] {
  const results: T[] = [];
  for (const file of anchor.files) {
    const text = windowText(ctx, file); if (text === undefined) continue;
    if (!fileGuard(text)) continue;
    const lines = text.split('\n');
    for (let i = 0; i < lines.length; i++) {
      if (!lineGuard(lines[i] ?? '')) continue;
      const win = windowFn(lines, i);
      const r = onMatch(file, lines, i, win);
      if (r !== null) results.push(r);
    }
  }
  return results;
}

