/** Runs ripwire and returns either an early-return RipwireLeg (absent/fail) or null
 *  meaning the caller should proceed to parse stdout. */
function runOrLeg(
  root: string,
  args: string[],
  opts?: { timeoutMs?: number; env?: NodeJS.ProcessEnv },
): { run: RawRun; earlyLeg: null } | { earlyLeg: RipwireLeg } {
  const run = runRaw(root, args, opts?.timeoutMs, opts?.env);
  if (!run.bin) return { earlyLeg: absentLeg("ripwire binary not found (set RIPWIRE_BIN)") };
  if (run.execError) return { earlyLeg: failLeg(run, `exec error: ${run.execError}`) };
  return { run, earlyLeg: null };
}

